<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Catalogue_Audit{
 public function run(int $limit=0):array{if(!function_exists('wc_get_products'))return array('summary'=>array('error'=>'WooCommerce is not active.'),'issue_counts'=>array(),'issues'=>array());$query=array('status'=>'publish','return'=>'ids','limit'=>$limit>0?min(5000,$limit):-1,'orderby'=>'ID','order'=>'ASC');$ids=array_map('absint',wc_get_products($query));$issues=array();$sku_map=array();$variable=0;$variations=0;foreach($ids as$id){$p=wc_get_product($id);if(!$p)continue;$name=$p->get_name();$short=trim(wp_strip_all_tags($p->get_short_description()));$description=trim(wp_strip_all_tags($p->get_description()));$text=strtolower($name.' '.$short.' '.$description.' '.implode(' ',wp_get_post_terms($id,'product_cat',array('fields'=>'names'))?:array()).' '.wp_json_encode($this->attributes($p)));$sku=trim((string)$p->get_sku());if($sku==='')$this->issue($issues,$id,$name,'missing_sku','Product has no SKU.');else$sku_map[strtolower($sku)][]=$id;if($short===''&&$description==='')$this->issue($issues,$id,$name,'missing_description','Product has no description.');elseif(mb_strlen($short.' '.$description)<80)$this->issue($issues,$id,$name,'short_description','Combined description is under 80 characters.');$cats=wp_get_post_terms($id,'product_cat',array('fields'=>'names'));if(is_wp_error($cats)||!array_filter($cats,static fn($v)=>strtolower((string)$v)!=='uncategorized'))$this->issue($issues,$id,$name,'missing_category','Product has no useful category.');if(!$p->get_image_id())$this->issue($issues,$id,$name,'missing_image','Product has no featured image.');if($p->get_price()==='')$this->issue($issues,$id,$name,'missing_price','Product has no active price.');if($this->is_application_product($text)&&!preg_match('/\b(floor|wall|ceiling|exterior|external|outdoor|interior|internal|masonry|concrete|wood|metal|plaster|brick|roof|tile|bathroom|kitchen|garage)\b/',$text))$this->issue($issues,$id,$name,'suitability_unknown','Description does not establish a surface or use environment.');if(preg_match('/\b(floor|garage|epoxy)\b/',$text)&&preg_match('/walls? and ceilings?|walls? only|ceilings? only/',$text)&&!preg_match('/suitable for[^.]{0,80}\bfloor/',$text))$this->issue($issues,$id,$name,'suitability_conflict','Floor-related product text conflicts with wall/ceiling-only suitability.');if($p->is_type('variable')){$variable++;$children=$p->get_children();if(!$children)$this->issue($issues,$id,$name,'variable_no_variations','Variable product has no variations.');foreach($children as$child_id){$v=wc_get_product($child_id);if(!$v)continue;$variations++;if($v->get_price()==='')$this->issue($issues,$id,$name,'variation_missing_price','Variation #'.$child_id.' has no price.',$child_id);$attrs=$v->get_variation_attributes();if(!$attrs||!array_filter($attrs,static fn($value)=>trim((string)$value)!==''))$this->issue($issues,$id,$name,'variation_missing_attributes','Variation #'.$child_id.' has no selected attributes.',$child_id);}}}foreach($sku_map as$sku=>$product_ids)if(count($product_ids)>1)foreach($product_ids as$id){$p=wc_get_product($id);$this->issue($issues,$id,$p?$p->get_name():'','duplicate_sku','SKU "'.$sku.'" is used by '.count($product_ids).' products.');}$counts=array_count_values(array_column($issues,'code'));ksort($counts);$affected=count(array_unique(array_column($issues,'product_id')));$total=count($ids);return array('summary'=>array('products_checked'=>$total,'variable_products'=>$variable,'variations_checked'=>$variations,'products_with_issues'=>$affected,'ready_products'=>max(0,$total-$affected),'readiness_percent'=>$total?round(($total-$affected)/$total*100,1):0,'total_issues'=>count($issues)),'issue_counts'=>$counts,'issues'=>$issues);}
 private function issue(array &$issues,int $product_id,string $name,string $code,string $message,int $variation_id=0):void{$issues[]=array('product_id'=>$product_id,'variation_id'=>$variation_id,'product'=>$name,'code'=>$code,'message'=>$message);}
 private function is_application_product(string $text):bool{return(bool)preg_match('/\b(paint|primer|coating|varnish|sealer|sealant|filler|adhesive|mortar|render|stain|undercoat)\b/',$text);}
 private function attributes(WC_Product $p):array{$out=array();foreach($p->get_attributes()as$a){$name=$a->get_name();$out[$name]=$a->is_taxonomy()?wc_get_product_terms($p->get_id(),$name,array('fields'=>'names')):$a->get_options();}return$out;}
}
